  ('fc2bdf71-089f-432c-afa1-e386ad327628', $q$کپاس کی اگیتی کاشت کے لئے موزوں علاقے فیصل آباد، ساہیوال، سرگودھا اور ملتان ڈویژنز کے اضلاع زیادہ موزوں ہیں۔$q$, $q$کپاس کی اگیتی کاشت کے موزوں علاقے$q$, NULL, 'ur', TRUE),
  ('d3b87612-4f7c-44b7-b0fd-30b2c3bc789d', $q$کپاس کی اگیتی کاشت کے لئے وقت کاشت وسط فروری تا 31 مارچ ہے۔$q$, $q$کپاس کی اگیتی کاشت کا وقت کاشت$q$, NULL, 'ur', TRUE),
  ('94b788ff-0cb7-4123-9d8f-cf75b7d59095', $q$کپاس کی اگیتی کاشت کے لئے پودوں کی فی ایکڑ تعداد موسمی کاشت کی نسبت کم تجویز کی جاتی ہے لہذا پودوں کی فی ایکڑ تعداد کے تعین کے لئے وقت کاشت، زمین کی زرخیزی، کپاس کی قسم ہمر دار شاخوں کی لمبائی اور غیر ثمر دار شاخوں کی تعداد کو مد نظر رکھتے ہوئے محکمہ زراعت کے مقامی عملہ سے مشورہ کریں عام طور پر کپاس کی اگیتی کاشت کے لئے پودوں کا باہمی فاصلہ اور قطاروں کا باہمی فاصلہ مندرجہ ذیل ہونا چاہیئے قطاروں کا باہمی فاصلہ 2.5 فٹ پودوں کا باہمی فاصلہ 1.5 تا 2 فٹ تک ہے۔$q$, $q$کپاس کی اگیتی کاشت کے لئے پودوں اور قطاروں کا باہمی فاصلہ$q$, NULL, 'ur', TRUE),
