  ('4df00108-e000-4269-8561-cf48a7fda070', $q$کپاس کی بہتر چنائی کا طریقہ یہ ہے کہ کپاس میں آلودگی سے پاک اور بہتر چنائی کے لئے مندرجہ ذیل باتوں کا خاص خیال رکھا جائے کپاس کی چنائی اس وقت شروع کی جائے جب تقریباً 40 تا 50 فیصد ٹینڈے کھل جائیں فصل پر شبنم خشک ہو جانے کے بعد چنائی کی جائے اور عموما چنائی کا صحیح وقت صبح 10 بجے کے بعد سے شروع ہوتا ہے اور شام 4 بجے چنائی بند کر دینی چاہیے اگر بارش کا امکان ہو تو چنائی نہ کی جائے بارش کے بعد چنائی اس وقت تک نہ کی جائے جب تک کھلی ہوئی کپاس (پھٹی) اچھی طرح خشک نہ ہو جائے چنائی اگر پودے کے نچلے حصے سے اوپر کی طرف کی جائے تو پودے کے سوکھے پتے چھٹی ہوئی کپاس ( پھٹی) میں شامل ہونے کے امکانات بہت کم ہو جاتے ہیں صرف اچھی طرح کھلے ہوئے ٹینڈوں کی چنائی کی جائے چنائی کرنے والوں کو پُر کشش معاوضہ دیا جائے تا کہ وہ چنائی کا وزن بڑھانے کے لئے کچے ٹینڈے توڑ کر کپاس میں شامل نہ کریں یاد رہے کہ کچے ٹینڈے کپاس کی کوالٹی کو خراب کرنے کا سبب بنتے ہیں چنائی کرنے والوں کی اجرت کپاس ( چھٹی) کی مقدار کے ساتھ ساتھ اس کی صفائی اور ستھرائی کی بناء پر مقرر کی جائے تا کہ چنائی کرنے والے کپاس ( پھٹی) کے معیار پر زیادہ توجہ دیں چنی ہوئی کپاس کو کھیت میں گیلی اور نمدار جگہ پر نہ رکھا جائے بلکہ خشک جگہ پر سوتی کپڑا بچھا کر اس پر رکھا جائے تا کہ پھٹی آلودگی سے محفوظ رہے کھیت میں گھری ہوئی کپاس ،گھاس پھویں اور پتوں وغیرہ سے آلودہ ہوتی ہے اس کو صاف ستھری کپاس میں نہ ملا ئیں بلکہ اسے علیحدہ رکھیں کھلے ہوئے ٹینڈوں کی چنائی کو را یعنی شدید سردی پڑنے سے قبل مکمل کر لیں تا کہ بنولے کی کوالٹی خراب نہ ہو آخری چنائی والی کپاس کا ریشہ کمزور اور بیج اُگنے کے قابل نہیں رہتا، لہذا آخری چنائی کو ہمیشہ علیحد رکھیں امریکن کپاس کی چنائی 15 تا 20 اور دیسی کپاس کی چنائی 8 دن کے وقفہ سے کریں تا کہ کھلی ہوئی کپاس ضائع نہ ہو کپاس کی مختلف اقسام الگ الگ گوداموں میں رکھیں تا کہ ریشہ اور بیج کی کوالٹی آپس میں مل کر متاثر نہ ہو گلابی سنڈی سے متاثرہ ٹینڈوں کی چتائی بالکل علیحد درکھیں ورنہ اس میں پیلا ہٹ والی کپاس شامل ہونے سے اسکے گریڈ میں کمی ہو جائے گی اور اس کا بھاؤ بہت کم لگے گا۔ کیونکہ کپڑا بننے کے دوران ایسی کیاس پر رنگائی کا عمل صحیح نہیں ہو یا تا چنائی کرنے والوں کو ایک ہنرمند سپروائزر کی نگرانی میں ایک قطار میں ایک ہی سمت چلنا چاہیے کپاس کی چنائی کے لئے استعمال ہونے والا کپڑا ( مجھولی) سوتی ہونا چاہیے پھٹی کو کھیت سے جنگ فیکٹری یا سٹور تک منتقل کرنے کے لئے پٹ سن، پولی تھین / پولی پراپلین اور پلاسٹک وغیرہ کے بورے وغیرہ استعمال میں نہ لا ئیں بلکہ سوتی کپڑے کے بورے استعمال کریں تا کہ کپاس آلودگی سے پاک رہے چنائی کرنے والوں کو چاہیے کہ اپنے سر کو اچھی طرح ڈھانپ کر چنائی کریں تا کہ اس میں بال وغیرہ نیل سکیں اور روئی کی کوالٹی متاثر نہ ہو۔$q$, $q$کپاس کی بہتر چنائی$q$, NULL, 'ur', TRUE),
  ('bff72aa3-7384-4065-be48-4f925fd7aef7', $q$کپاس کو سٹور میں رکھنے کا طریقہ یہ ہے کہ سٹور میں کپاس کی کوالٹی کو خراب ہونے سے بچانے کے لیے مندرجہ ذیل باتوں کا خاص خیال رکھا جائے سٹور میں رکھی جانے والی کپاس میں نمی 8 تا 10 فیصد سے زیادہ نہیں ہونی چاہیے سٹور ہوا دار اور اس کا فرش پختہ اور خشک ہونا چاہیے اگر سٹور کا فرش کچا ہو تو پلاسٹک ضرور بچھانا چاہیے بہتر یہ ہے کہ پہلے خشک ریت کی تہہ بچھا کر اس پر پلاسٹک بچھایا جائے اور پھر پلاسٹک کے اوپر کپاس رکھی جائے سٹور میں کپاس کو مناسب جسامت کے موصلی شکل کے ڈھیروں میں اس طرح رکھا جائے کہ ان ڈھیروں کے درمیان کچھ فاصلہ ہوتا کہ ہوا کا گزر با آسانی ہو سکے سٹور میں کپاس کو قسم کے لحاظ سے اس طرح رکھا جائے کہ ان اقسام کا آپس میں ملنے کا کوئی اندیشہ نہ ہو سٹور میسر نہ ہونے کی صورت میں کپاس کو کپڑے کے بوروں میں بھر کر رکھنا چاہیے تاہم اگر کپاس کو باہر اور کھلا رکھنا مقصود ہوتو اونچی اور خشک زمین پر ریت کی پتلی سی تہہ پر پلاسٹک بچھا کر اس کے اوپر موصلی نماز ھیروں میں رکھا جائے بارش ہونے کی صورت میں ڈھیروں کو تر پالوں سے ڈھانپ دیا جائے جب مطلع صاف ہو جائے تو ترپالیں ڈھیروں سے اتار دیں اور کوشش کریں کہ باہر کھلے آسمان تلے رکھی ہوئی کپاس کو جلد از جلد فروخت کر دیا جائے۔$q$, $q$کپاس کو سٹور میں رکھنے کا طریقہ$q$, NULL, 'ur', TRUE),
  ('bbb9938e-b060-460c-a1d6-8e30d97c1b34', $q$کپاس کی برداشت کے بعد کے اقدامات یہ ہیں کہ کپاس میں بیج کے طور پر سٹور کی گئی پھٹی میں ایلومینیم فاسفائیڈ کی 30 گولیاں فی ہزار مکعب فٹ رکھی جائیں تا کہ گلابی سنڈی جو جڑے ہوئے بیجوں میں ہو دو تلف ہو جائے آخری چنائی کے بعد 31 دسمبر تک چھڑیوں کو رونا ویٹر کی مدد سے کھیت میں دبا دیں یا پھر کاٹ کر کھیت سے باہر نکال دیں اور گہرا ہل چلا دیں تا کہ زمین میں موجود سنڈیوں کے پیو پے تلف ہو جائیں کپاس کی چھڑیاں جو کہ کاشتکار ایندھن کے طور پر استعمال کرتے ہیں ان کو کپاس کے کھیتوں سے دور چھوٹی چھوٹی ڈھیریوں میں عمودی حالت میں رکھا جائے یہ ڈھیری 5 فٹ سے اونچی نہ ہوتا کہ سورج کی روشنی بچے کھچے ٹینڈوں پر پڑے اور ان میں موجود گلابی سنڈی کپاس کی فصل سے پہلے ہی پر دانہ بن کر باہر آ جائے اور کپاس کی فصل نہ ملنے پر اپنی موت آپ مرجائے۔$q$, $q$کپاس کی برداشت$q$, NULL, 'ur', TRUE),
  ('2ff37b8d-cc80-47e1-87a5-1782ba317255', $q$کپاس کی بہتر پیداوار کرنے کا طریقہ یہ ہے کہ کپاس میں شرح بیج کا تعین بیج کے فیصد گاؤ اور وقت کاشت، کپاس کی قسم اور طریقہ کاشت کو مد نظر رکھتے ہوئے دی گئی سفارشات کے مطابق کریں پیچ کو سفارش کردہ پھپھوندی کش اور کیڑے مار زہر لگا کر کاشت کریں کپاس میں ڈرل کاشتہ فصل میں چھدرائی پہلی آبپاشی سے پہلے مکمل کریں اور چھدرائی کرتے وقت کمزور اور بیمار پودوں کو ضرور نکال دیں تا کہ فصل تندرست اور توانا ہو پودوں کی فی ایکڑ تعداد کا تعین وقت کاشت ، زمین کی زرخیزی اور کپاس کی قسم کو مد نظر رکھتے ہوئے دی گئی سفارشات کے مطابق کریں کاشت پٹڑیوں پر کریں، ہموار زمین پر قطاروں میں کاشت کی صورت میں قطاروں کا درمیانی فاصلہ اڑھائی فٹ رکھیں، جب اس کا قد ڈیڑھ تا دو فٹ ہو جائے تو ہر دوسری لائن میں پودوں کے ساتھ مٹی چڑھا دیں، اس طرح پڑ یاں بن جائیں گی کھیتوں میں اور ان کے ارد گرد پائی جانے والی سفید کبھی ہلی بگ اور لیف کرل وائرس کے میزبان پودے اور جڑی بوٹیاں بر وقت تلف کریں بہاریہ فصلات خاص طور پر سبزیوں کی باقیات جلد از جلد ختم کر دیں اور کیڑوں کے انسداد کے لیے مربوط تحفظ نباتات ( آئی پی ایم ) کے طریقے اختیار کریں مناسب کھادوں کا متوازن استعمال مٹی کے لیبارٹری تجزیہ، کپاس کی قسم ، علاقہ اور وقت کاشت کو مد نظر رکھتے ہوئے دی گئی سفارشات کے مطابق کریں " کھا د حساب" (موبائل ایپ) کے ذریعے کپاس کی فصل کے لئے کھادوں کی مطلوبہ مقدار کا حساب لگائیں اور ان کے استعمال سے پیدا وار اور منافع میں اضافہ کریں اگر فاسفورسی کھاد بوائی کے وقت نہیں ڈالی جاسکی تو چھدرائی کے بعد پانی لگانے سے پہلے ڈالیں فصل کو پہلا پانی وقت کاشت ، طریقہ کاشت ، موسمی صورت حال اور فصل کی ضرورت کے مطابق لگا ئیں جڑی بوٹیوں کی تلفی کے لئے سفارش کردہ طریقہ کار بر وقت بروئے کارلائیں زیادہ بارش کی صورت میں کھیتوں سے زائد پانی نکالنے کا فوری بندوبست کریں اور زائد پانی کے نقصان سے بچانے کے لئے اس ضمن میں دی گئی سفارشات پر عمل کریں پیسٹ سکاؤٹنگ کی بنیاد پر نقصان دہ کیڑوں کا بر وقت تدارک کریں اور ٹینڈوں کے کھلنے تک تدارک جاری رکھیں۔$q$, $q$کپاس کی بہتر پیداوار کرنے کا طریقہ$q$, NULL, 'ur', TRUE);
